import Foundation
import AppKit
let path = NSHomeDirectory()+"/Developer/ai/week9-previs-20261108/memo-os/week-9/WEEK_9_COMPLETE_ISSUE_PREVIS_2026-11-08.json"
let doc = try JSONSerialization.jsonObject(with: Data(contentsOf: URL(fileURLWithPath:path))) as! [String:Any]
var results = [String:Any]()
for p in doc["pages"] as! [[String:Any]] {
 guard let prep = p["proof_preparation"] as? [String:Any] else {continue}
 let id=p["page_id"] as! String, text=prep["body_copy"] as! String
 let style=NSMutableParagraphStyle();style.minimumLineHeight=43;style.maximumLineHeight=43;style.lineBreakMode = .byWordWrapping
 let font=NSFont(name:"Arial",size:34)!
 let rect=(text as NSString).boundingRect(with:NSSize(width:960,height:1000),options:[.usesLineFragmentOrigin,.usesFontLeading],attributes:[.font:font,.paragraphStyle:style])
 let height=ceil(rect.height)
 precondition(height<=370,"Body copy exceeds reserved box")
 results[id] = ["engine":"macOS AppKit", "font":"Arial 34; line height 43", "measured_height":height,"reserved_height":370,"text_fit":true,"phone_visual_QA":false]
}
let data=try JSONSerialization.data(withJSONObject:results,options:[.prettyPrinted,.sortedKeys]);try data.write(to:URL(fileURLWithPath:"/tmp/week9-proof-text-fit.json"));print(String(data:data,encoding:.utf8)!)
